// Finite-state machine that starts, waits, and resets a timer when a
// particular sequence of bits is detected.
module TopModule(clk, reset, data, done_counting, ack, shift_ena, counting, done);
    input  clk;
    input  reset;
    input  data;
    input  done_counting;
    input  ack;
    output shift_ena;
    output counting;
    output done;
    reg [2:0] state;
    reg [2:0] next_state;
    wire pattern_detected;
    reg [3:0] shift_reg;
    wire [3:0] delay;
    reg counting_reg;
    wire counting_done;
    reg done_reg;
    reg shift_ena_reg;
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'd0;
            shift_reg <= 4'd0;
            counting_reg <= 1'd0;
            done_reg <= 1'd0;
            shift_ena_reg <= 1'd0;
        end else begin
            state <= next_state;
            if (shift_ena_reg) begin
                shift_reg <= {data, shift_reg[3:1]};
            end
            counting_reg <= (state == 3'd1) ? 1'd1 : (counting_done ? 1'd0 : counting_reg);
            done_reg <= (state == 3'd2) ? 1'd1 : (ack ? 1'd0 : done_reg);
            shift_ena_reg <= (state == 3'd0) ? 1'd1 : (state == 3'd1) ? 1'd1 : 1'd0;
        end
    end
    assign pattern_detected = (shift_reg == 4'b1101);
    assign delay = {shift_reg[0], shift_reg[1], shift_reg[2], shift_reg[3]};
    assign counting_done = (state == 3'd1) & done_counting;
    always @* begin
        case (state)
            3'd0: next_state = pattern_detected ? 3'd1 : 3'd0;
            3'd1: next_state = counting_done ? 3'd2 : 3'd1;
            3'd2: next_state = ack ? 3'd0 : 3'd2;
            default: next_state = 3'd0;
        endcase
    end
    assign shift_ena = shift_ena_reg;
    assign counting = counting_reg;
    assign done = done_reg;
endmodule

