// Finite-state machine that implements the described timer
module TopModule(input clk, input reset, input data, input done_counting, input ack,
                 output reg shift_ena, output reg counting, output reg done);
    reg [3:0] pattern;
    reg [2:0] state;
    reg [2:0] next_state;
    reg [3:0] delay;
    always @(*) begin
        case(state)
            3'b000: if(pattern == 4'b1101) next_state = 3'b001; else next_state = 3'b000;
            3'b001: if(pattern == 4'b1101) next_state = 3'b010; else next_state = 3'b000;
            3'b010: if(pattern == 4'b1101) next_state = 3'b011; else next_state = 3'b000;
            3'b011: if(pattern == 4'b1101) next_state = 3'b100; else next_state = 3'b000;
            3'b100: if(done_counting) next_state = 3'b101; else next_state = 3'b100;
            3'b101: if(ack) next_state = 3'b000; else next_state = 3'b101;
            default: next_state = 3'b000;
        endcase
    end
    always @(posedge clk) begin
        if(reset) begin state <= 3'b000; shift_ena <= 0; counting <= 0; done <= 0; pattern <= 4'b0000; delay <= 3'b000; end
        else begin
            state <= next_state;
            shift_ena <= 0;
            counting <= 0;
            done <= 0;
            case(state)
                3'b001: shift_ena <= 1;
                3'b010: delay <= {1'b0, data, 1'b0};
                3'b011: delay <= {data, 2'b00};
                3'b100: counting <= 1;
                3'b101: done <= 1;
            endcase
            pattern <= {data, pattern[3:1]};
        end
    end
endmodule

