// Timer FSM: implements the time-out sequence (1101) plus a delay determined
// by another 4 bits. The counting signal is asserted for one clock cycle
// after the 5-bit sequence is received, and waits for done_counting to go
// high before asserting done and waiting for ack.
module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);
    reg [2:0] state;
    reg [2:0] next_state;
    reg [3:0] delay_counter;
    reg [3:0] next_delay_counter;
    reg [4:0] bit_counter;
    reg [4:0] next_bit_counter;
    wire [4:0] pattern = 5'b11010;
    wire [4:0] shifted_data;
    wire pattern_detected;
    reg counting_reg;
    reg done_reg;
    assign shifted_data = {data, shifted_data[4:1]};
    assign pattern_detected = (shifted_data == pattern);
    always @* begin
        next_state = state;
        next_delay_counter = delay_counter;
        next_bit_counter = bit_counter;
        shift_ena = 1'b0;
        counting_reg = 1'b0;
        done_reg = 1'b0;
        case (state)
            3'd0: begin // Search for pattern 1101
                if (pattern_detected) begin
                    next_state = 3'd1;
                    next_delay_counter = 3'd0;
                    shift_ena = 1'b1;
                end
            end
            3'd1: begin // Delay for the determined number of clock cycles
                if (delay_counter == 3'd4) begin
                    next_state = 3'd2;
                    counting_reg = 1'b1;
                end else begin
                    next_delay_counter = delay_counter + 3'd1;
                end
            end
            3'd2: begin // Wait for done_counting
                if (done_counting) begin
                    next_state = 3'd3;
                end
            end
            3'd3: begin // Notify the user and wait for ack
                done_reg = 1'b1;
                if (ack) begin
                    next_state = 3'd0;
                end
            end
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'd0;
            delay_counter <= 3'd0;
            bit_counter <= 5'd0;
        end else begin
            state <= next_state;
            delay_counter <= next_delay_counter;
            bit_counter <= next_bit_counter;
            if (shift_ena) begin
                bit_counter <= bit_counter + 5'd1;
            end
        end
    end
    assign counting = counting_reg;
    assign done = done_reg;
endmodule

