// One-bit timer finite-state machine. The long-running combinational path
// (the "state-dependent latching" part of the FSM) is split off into a
// separate register-transfer function (RTF).
module TopModule(input clk, input reset, input data, input done_counting, input ack, output reg shift_ena, output reg counting, output reg done);
  reg [3:0] state;
  reg [3:0] pattern;
  reg [3:0] delay;
  reg [3:0] count;
  reg [3:0] next_state;
  reg [3:0] next_pattern;
  reg [3:0] next_delay;
  reg [3:0] next_count;
  wire go;
  wire [3:0] next_count_inc;
  reg [3:0] next_count_inc_reg;
  wire [3:0] next_count_dec;
  reg [3:0] next_count_dec_reg;
  wire [3:0] next_delay_dec;
  reg [3:0] next_delay_dec_reg;
  always @(*) begin
    go = (state == 4);
    next_count_inc = count + 1;
    next_count_dec = count - 1;
    next_delay_dec = delay - 1;
  end
  always @(posedge clk) begin
    next_count_inc_reg <= next_count_inc;
    next_count_dec_reg <= next_count_dec;
    next_delay_dec_reg <= next_delay_dec;
    if (reset) begin
      state <= 0;
      pattern <= 0;
      delay <= 0;
      count <= 0;
    end else begin
      state <= next_state;
      pattern <= next_pattern;
      delay <= next_delay;
      count <= next_count;
    end
    if (go) begin
      if (count == 0) begin
        shift_ena <= 1;
      end
      if (count == 1) begin
        shift_ena <= 0;
        counting <= 1;
      end
      if (count == 2 && done_counting) begin
        counting <= 0;
        done <= 1;
      end
      if (count == 3 && ack) begin
        done <= 0;
        state <= 0;
        pattern <= 0;
        delay <= 0;
        count <= 0;
      end
    end
  end
  always @(*) begin
    next_state = state;
    next_pattern = pattern;
    next_delay = delay;
    next_count = count;
    case (state)
      0: begin
        if (data) begin
          next_state = 1;
          next_pattern = 1;
        end
      end
      1: begin
        if (data) begin
          next_state = 2;
          next_pattern = 2;
        end else begin
          next_state = 0;
          next_pattern = 0;
        end
      end
      2: begin
        if (data) begin
          next_state = 3;
          next_pattern = 3;
        end else begin
          next_state = 0;
          next_pattern = 0;
        end
      end
      3: begin
        if (data) begin
          next_state = 4;
          next_pattern = 4;
          next_delay = 4;
        end else begin
          next_state = 0;
          next_pattern = 0;
        end
      end
      4: begin
        if (count < 3) begin
          next_count = next_count_inc_reg;
        end
        if (count == 3 && done_counting) begin
          next_state = 5;
          next_count = 0;
        end
      end
      5: begin
        if (count < 2) begin
          next_count = next_count_inc_reg;
        end
        if (count == 2 && ack) begin
          next_state = 0;
          next_count = 0;
        end
        if (count == 2 && !ack) begin
          next_state = 4;
          next_count = 0;
        end
      end
    endcase
  end
endmodule

