// finite-state machine for the timer (counting only when enabled, and
// notifying the user when the countdown is done). The data path (counters
// and comparators) is not included here.
module TopModule(
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output reg shift_ena,
    output reg counting,
    output reg done
);
    reg [2:0] state;
    reg [2:0] next_state;
    reg [2:0] delay;
    reg [3:0] pattern;
    wire match;
    wire match2;
    assign match = (pattern == 3'b1101);
    assign match2 = (pattern == 3'b1111);
    always @(*) begin
        case (state)
            3'd0: next_state = match ? 3'd1 : 3'd0;
            3'd1: next_state = match2 ? 3'd2 : 3'd0;
            3'd2: next_state = done_counting ? 3'd3 : 3'd2;
            3'd3: next_state = ack ? 3'd0 : 3'd4;
            3'd4: next_state = match ? 3'd1 : 3'd0;
            default: next_state = 3'd0;
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'd0;
            delay <= 3'd0;
            pattern <= 3'd0;
            counting <= 1'b0;
            done <= 1'b0;
            shift_ena <= 1'b0;
        end else begin
            state <= next_state;
            delay <= (state == 3'd1) ? 3'd4 : delay - 1;
            pattern <= {data, pattern[2:1]};
            counting <= (state == 3'd2);
            done <= (state == 3'd3);
            shift_ena <= (state == 3'd1) & (delay == 3'd0);
        end
    end
endmodule

