// Timer finite-state machine
module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output reg shift_ena,
    output reg counting,
    output reg done
);
    reg [31:0] counter;
    reg [3:0] shift_reg;
    reg [3:0] pattern = 4'b1101;
    reg [1:0] state;
    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
            shift_reg <= 4'b0;
            state <= 2'b00;
            shift_ena <= 1'b0;
            counting <= 1'b0;
            done <= 1'b0;
        end else begin
            case (state)
                2'b00: begin // search for start pattern
                    if (shift_reg == pattern) begin
                        counter <= 0;
                        shift_ena <= 1'b1;
                        state <= 2'b01;
                    end else begin
                        shift_ena <= 1'b0;
                    end
                    shift_reg <= {shift_reg[2:0], data};
                end
                2'b01: begin // waiting for counters to finish counting
                    shift_ena <= 1'b0;
                    if (counter == 15) begin // 16 cycles = 1 microsecond
                        counting <= 1'b1;
                        state <= 2'b10;
                    end else begin
                        counter <= counter + 1;
                    end
                end
                2'b10: begin // waiting for ack
                    counting <= 1'b0;
                    if (done_counting) begin
                        done <= 1'b1;
                        state <= 2'b11;
                    end
                    if (ack) begin
                        done <= 1'b0;
                        state <= 2'b00;
                    end
                end
                2'b11: begin // waiting for ack
                    if (ack) state <= 2'b00;
                end
            endcase
        end
    end
endmodule

