// The finite-state machine that controls the timer.
module FSM (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);
    reg [2:0] state;
    reg [2:0] next_state;
    reg [2:0] pattern;
    reg [2:0] next_pattern;
    reg [3:0] count;
    reg [3:0] next_count;
    wire pattern_detected;
    wire shift_ena;
    wire counting;
    wire done;
    assign pattern_detected = (pattern == 3'b1101);
    assign shift_ena = (state == 3'b000);
    assign counting = (state != 3'b000);
    assign done = (state == 3'b100);
    always @(*) begin
        next_state = state;
        next_pattern = pattern;
        next_count = count;
        case (state)
            3'b000: begin
                if (pattern_detected) next_state = 3'b001;
                else next_pattern = {data, pattern[2:1]};
            end
            3'b001: begin
                next_state = 3'b010;
                next_count = 4;
            end
            3'b010: begin
                if (count == 1) next_state = 3'b011;
                else next_count = count - 1;
            end
            3'b011: begin
                if (done_counting) next_state = 3'b100;
            end
            3'b100: begin
                if (ack) next_state = 3'b000;
            end
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'b000;
            pattern <= 3'b000;
            count <= 4'd0;
        end
        else begin
            state <= next_state;
            pattern <= next_pattern;
            count <= next_count;
        end
    end
endmodule

